SELECT COUNT(*)
FROM district
WHERE A11 > 6000 AND A11 < 10000;

SELECT 100.0 * SUM(CASE WHEN isTextless = 1 AND layout = 'normal' THEN 1 ELSE 0 END)
       / NULLIF(SUM(CASE WHEN isTextless = 1 THEN 1 ELSE 0 END), 0) AS proportion
FROM cards;

SELECT 'Serra Angel' AS card_name
WHERE (SELECT MAX(convertedManaCost) FROM cards WHERE name = 'Serra Angel')
    > (SELECT MAX(convertedManaCost) FROM cards WHERE name = 'Shrine Keeper');

SELECT Text
FROM comments
WHERE Score = 17;

SELECT id
FROM publisher
WHERE publisher_name = 'Star Trek';

SELECT 100.0 * COUNT(CASE WHEN CAST(strftime('%Y', Birthday) AS INTEGER) > 1930 THEN ID END) / COUNT(ID) AS percentage
FROM Patient
WHERE SEX = 'F';

SELECT SUM(spent)
FROM budget
WHERE category = 'Food';
